-- Console schema for sqlite, generated by `scripts/dump_schema_sql.py` from `alembic upgrade head --sql`.
-- Do not edit: change `alembic/versions/` and re-run the script.
--
-- This file creates the tables *and* stamps `alembic_version`, so a database
-- initialised from it is already at head and `alembic upgrade head` is a no-op.
-- It is idempotent only in the sense that re-running it fails on the existing
-- tables — provision an empty database with it.
-- Needs SQLite 3.35+ (the version stamp is an INSERT ... RETURNING).

CREATE TABLE alembic_version (
    version_num VARCHAR(32) NOT NULL,
    CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);

-- Running upgrade  -> 0001_initial

CREATE TABLE param_user (
    id INTEGER NOT NULL,
    username VARCHAR(64) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    role VARCHAR(16) DEFAULT 'operator' NOT NULL,
    disabled BOOLEAN DEFAULT 0 NOT NULL,
    created_at DATETIME NOT NULL,
    last_login_at DATETIME,
    PRIMARY KEY (id),
    UNIQUE (username)
);

CREATE TABLE param_draft (
    id INTEGER NOT NULL,
    profile VARCHAR(64) NOT NULL,
    base_version INTEGER DEFAULT '0' NOT NULL,
    patch JSON NOT NULL,
    updated_by VARCHAR(64) DEFAULT '' NOT NULL,
    updated_at DATETIME NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (profile)
);

CREATE TABLE param_version (
    id INTEGER NOT NULL,
    profile VARCHAR(64) NOT NULL,
    version INTEGER NOT NULL,
    status VARCHAR(16) NOT NULL,
    note VARCHAR(500) DEFAULT '' NOT NULL,
    author VARCHAR(64) DEFAULT '' NOT NULL,
    yaml_text TEXT DEFAULT '' NOT NULL,
    yaml_sha256 VARCHAR(64) DEFAULT '' NOT NULL,
    env_sha256 VARCHAR(64) DEFAULT '' NOT NULL,
    duration_s FLOAT,
    rolled_back_to INTEGER,
    error_code VARCHAR(48),
    created_at DATETIME NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_param_version_profile_version UNIQUE (profile, version)
);

CREATE TABLE param_audit (
    id INTEGER NOT NULL,
    at DATETIME NOT NULL,
    actor VARCHAR(64) DEFAULT '' NOT NULL,
    role VARCHAR(16) DEFAULT '' NOT NULL,
    action VARCHAR(32) NOT NULL,
    profile VARCHAR(64) DEFAULT '' NOT NULL,
    version INTEGER,
    fields JSON NOT NULL,
    result VARCHAR(8) DEFAULT 'ok' NOT NULL,
    error_code VARCHAR(48),
    duration_s FLOAT,
    request_id VARCHAR(64) DEFAULT '' NOT NULL,
    PRIMARY KEY (id)
);

INSERT INTO alembic_version (version_num) VALUES ('0001_initial') RETURNING version_num;

-- Running upgrade 0001_initial -> 0003_voices

CREATE TABLE voices (
    id VARCHAR(26) NOT NULL,
    name VARCHAR(64) NOT NULL,
    source VARCHAR(16) NOT NULL,
    backend VARCHAR(16) NOT NULL,
    language VARCHAR(16),
    status VARCHAR(16) DEFAULT 'draft' NOT NULL,
    audio_relpath VARCHAR(255),
    audio_bytes INTEGER DEFAULT '0' NOT NULL,
    audio_seconds FLOAT DEFAULT '0' NOT NULL,
    trim_start_ms INTEGER DEFAULT '0' NOT NULL,
    trim_end_ms INTEGER,
    ref_text TEXT,
    instruct TEXT,
    spk_relpath VARCHAR(255),
    rvq_relpath VARCHAR(255),
    error_code VARCHAR(32),
    created_at DATETIME NOT NULL,
    created_by VARCHAR(64) NOT NULL,
    consent_ack_at DATETIME NOT NULL,
    retention_days INTEGER DEFAULT '30' NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_voices_name UNIQUE (name)
);

CREATE INDEX ix_voices_status ON voices (status);

UPDATE alembic_version SET version_num='0003_voices' WHERE alembic_version.version_num = '0001_initial';

-- Running upgrade 0003_voices -> 0004_turn_latency

CREATE TABLE turn_latency (
    response_key VARCHAR(96) NOT NULL,
    turn_revision INTEGER NOT NULL,
    turn_id VARCHAR(96),
    source VARCHAR(16) DEFAULT '' NOT NULL,
    status VARCHAR(16) DEFAULT '' NOT NULL,
    smart_status VARCHAR(16),
    e2e_ms INTEGER,
    stt_ms INTEGER,
    llm_ms INTEGER,
    tts_ttfa_ms INTEGER,
    vad_decision_ms INTEGER,
    hold_ms INTEGER,
    logged_at DATETIME NOT NULL,
    raw_offset INTEGER DEFAULT '0' NOT NULL,
    ingested_at DATETIME NOT NULL,
    PRIMARY KEY (response_key, turn_revision)
);

CREATE INDEX ix_turn_latency_logged_at ON turn_latency (logged_at);

UPDATE alembic_version SET version_num='0004_turn_latency' WHERE alembic_version.version_num = '0003_voices';

-- Running upgrade 0004_turn_latency -> 0005_instances

CREATE TABLE param_instance (
    id INTEGER NOT NULL,
    instance_id VARCHAR(64) NOT NULL,
    base_url VARCHAR(255) NOT NULL,
    weight INTEGER DEFAULT '1' NOT NULL,
    max_sessions_hint INTEGER,
    labels_json JSON NOT NULL,
    enabled BOOLEAN DEFAULT '1' NOT NULL,
    drain_requested BOOLEAN DEFAULT '0' NOT NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NOT NULL,
    updated_by VARCHAR(64) DEFAULT '' NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_param_instance_instance_id UNIQUE (instance_id)
);

CREATE TABLE param_instance_metric (
    id INTEGER NOT NULL,
    instance_id VARCHAR(64) NOT NULL,
    observed_at DATETIME NOT NULL,
    observed_by VARCHAR(64) NOT NULL,
    kind VARCHAR(16) DEFAULT 'sample' NOT NULL,
    size INTEGER,
    in_use INTEGER,
    free INTEGER,
    stuck INTEGER,
    status VARCHAR(16) NOT NULL,
    probe_ms INTEGER,
    alloc_ok INTEGER DEFAULT '0' NOT NULL,
    alloc_fail_no_instance INTEGER DEFAULT '0' NOT NULL,
    alloc_fail_instance_503 INTEGER DEFAULT '0' NOT NULL,
    evict_count INTEGER DEFAULT '0' NOT NULL,
    recover_count INTEGER DEFAULT '0' NOT NULL,
    PRIMARY KEY (id)
);

CREATE INDEX ix_param_instance_metric_instance_id ON param_instance_metric (instance_id);

CREATE INDEX ix_param_instance_metric_observed_at ON param_instance_metric (observed_at);

UPDATE alembic_version SET version_num='0005_instances' WHERE alembic_version.version_num = '0004_turn_latency';

-- Running upgrade 0005_instances -> 0006_clusters

CREATE TABLE param_cluster (
    id INTEGER NOT NULL,
    name VARCHAR(64) NOT NULL,
    registry VARCHAR(255) DEFAULT '' NOT NULL,
    policy VARCHAR(16) DEFAULT 'least' NOT NULL,
    note VARCHAR(255) DEFAULT '' NOT NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NOT NULL,
    updated_by VARCHAR(64) DEFAULT '' NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_param_cluster_name UNIQUE (name)
);

INSERT INTO param_cluster (name, registry, policy, note, created_at, updated_at, updated_by) SELECT 'default', '', 'least', '', datetime('now'), datetime('now'), 'migration' WHERE NOT EXISTS (SELECT 1 FROM param_cluster WHERE name = 'default');

ALTER TABLE param_instance ADD COLUMN cluster_id VARCHAR(64) DEFAULT 'default' NOT NULL;

CREATE INDEX ix_param_instance_cluster_id ON param_instance (cluster_id);

UPDATE alembic_version SET version_num='0006_clusters' WHERE alembic_version.version_num = '0005_instances';

-- Running upgrade 0006_clusters -> 0007_comments

UPDATE alembic_version SET version_num='0007_comments' WHERE alembic_version.version_num = '0006_clusters';

-- Running upgrade 0007_comments -> 0008_proxy_metrics

CREATE TABLE param_proxy_metric (
    id INTEGER NOT NULL,
    instance_id VARCHAR(64) NOT NULL,
    service VARCHAR(32) NOT NULL,
    observed_at DATETIME NOT NULL,
    observed_by VARCHAR(64) DEFAULT '' NOT NULL,
    ok INTEGER DEFAULT '0' NOT NULL,
    fail_count INTEGER DEFAULT '0' NOT NULL,
    fail_reason VARCHAR(64) DEFAULT '' NOT NULL,
    duration_ms INTEGER DEFAULT '0' NOT NULL,
    PRIMARY KEY (id)
);

CREATE INDEX ix_param_proxy_metric_instance_id ON param_proxy_metric (instance_id);

CREATE INDEX ix_param_proxy_metric_service ON param_proxy_metric (service);

CREATE INDEX ix_param_proxy_metric_observed_at ON param_proxy_metric (observed_at);

UPDATE alembic_version SET version_num='0008_proxy_metrics' WHERE alembic_version.version_num = '0007_comments';

-- Running upgrade 0008_proxy_metrics -> 0009_db_registry_and_config

CREATE TABLE param_config (
    id INTEGER NOT NULL,
    config_key VARCHAR(128) NOT NULL,
    value VARCHAR(1024) DEFAULT '' NOT NULL,
    value_type VARCHAR(16) DEFAULT 'str' NOT NULL,
    section VARCHAR(32) DEFAULT 'console' NOT NULL,
    description VARCHAR(255) DEFAULT '' NOT NULL,
    restart_required BOOLEAN DEFAULT '0' NOT NULL,
    version INTEGER DEFAULT '1' NOT NULL,
    updated_by VARCHAR(64) DEFAULT '' NOT NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_param_config_key UNIQUE (config_key)
);

CREATE TABLE param_instance_runtime (
    id INTEGER NOT NULL,
    instance_id VARCHAR(64) NOT NULL,
    status VARCHAR(16) DEFAULT 'unknown' NOT NULL,
    pool_size INTEGER,
    in_use INTEGER,
    stuck INTEGER,
    probe_ms INTEGER,
    capabilities JSON DEFAULT '[]' NOT NULL,
    capability_issues JSON DEFAULT '{}' NOT NULL,
    consecutive_failures INTEGER DEFAULT '0' NOT NULL,
    consecutive_successes INTEGER DEFAULT '0' NOT NULL,
    last_error VARCHAR(255) DEFAULT '' NOT NULL,
    probe_history JSON DEFAULT '[]' NOT NULL,
    reserved INTEGER DEFAULT '0' NOT NULL,
    observed_at DATETIME NOT NULL,
    observed_by VARCHAR(64) DEFAULT '' NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_param_instance_runtime_instance_id UNIQUE (instance_id)
);

CREATE TABLE param_allocator_lease (
    lease_key VARCHAR(128) NOT NULL,
    instance_id VARCHAR(64) NOT NULL,
    state VARCHAR(16) DEFAULT 'pending' NOT NULL,
    expires_at DATETIME,
    console_id VARCHAR(64) DEFAULT '' NOT NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NOT NULL,
    PRIMARY KEY (lease_key)
);

CREATE INDEX ix_param_allocator_lease_instance_id ON param_allocator_lease (instance_id);

CREATE INDEX ix_param_allocator_lease_state ON param_allocator_lease (state);

CREATE INDEX ix_param_allocator_lease_expires_at ON param_allocator_lease (expires_at);

UPDATE alembic_version SET version_num='0009_db_registry_and_config' WHERE alembic_version.version_num = '0008_proxy_metrics';

-- Running upgrade 0009_db_registry_and_config -> 0010_console_lb_backbone

CREATE TABLE param_machine (
    id INTEGER NOT NULL,
    machine_id VARCHAR(64) NOT NULL,
    cluster_id VARCHAR(64) DEFAULT '' NOT NULL,
    profile VARCHAR(64),
    addr VARCHAR(255) DEFAULT '' NOT NULL,
    role VARCHAR(16) DEFAULT 'agent' NOT NULL,
    gpu VARCHAR(64) DEFAULT '' NOT NULL,
    gpu_total_gb FLOAT,
    version VARCHAR(64) DEFAULT '' NOT NULL,
    state VARCHAR(16) DEFAULT 'pending_register' NOT NULL,
    registry_mode VARCHAR(16) DEFAULT 'manual' NOT NULL,
    agent_version VARCHAR(64) DEFAULT '' NOT NULL,
    protocol_version INTEGER DEFAULT '1' NOT NULL,
    agent_caps JSON DEFAULT '[]' NOT NULL,
    token_hash VARCHAR(64),
    register_code_hash VARCHAR(64),
    last_seen_at DATETIME,
    created_by VARCHAR(64) DEFAULT '' NOT NULL,
    updated_by VARCHAR(64) DEFAULT '' NOT NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_param_machine_machine_id UNIQUE (machine_id),
    CONSTRAINT uq_param_machine_token_hash UNIQUE (token_hash),
    CONSTRAINT uq_param_machine_register_code_hash UNIQUE (register_code_hash)
);

CREATE INDEX ix_param_machine_cluster_id ON param_machine (cluster_id);

CREATE TABLE param_machine_workload (
    id INTEGER NOT NULL,
    machine_id VARCHAR(64) NOT NULL,
    kind VARCHAR(16) DEFAULT 'pipeline' NOT NULL,
    engine VARCHAR(64) DEFAULT '' NOT NULL,
    model VARCHAR(128) DEFAULT '' NOT NULL,
    port INTEGER,
    listen_addr VARCHAR(64) DEFAULT '' NOT NULL,
    public_addr VARCHAR(64) DEFAULT '' NOT NULL,
    vram_gb FLOAT,
    health_path VARCHAR(255) DEFAULT '' NOT NULL,
    health_interval_s INTEGER DEFAULT '30' NOT NULL,
    note VARCHAR(255) DEFAULT '' NOT NULL,
    state VARCHAR(16) DEFAULT '' NOT NULL,
    updated_at DATETIME NOT NULL,
    PRIMARY KEY (id)
);

CREATE INDEX ix_param_machine_workload_machine_id ON param_machine_workload (machine_id);

CREATE TABLE param_machine_config (
    id INTEGER NOT NULL,
    machine_id VARCHAR(64) NOT NULL,
    param_key VARCHAR(128) NOT NULL,
    actual_value VARCHAR(1024) DEFAULT '' NOT NULL,
    config_version INTEGER DEFAULT '0' NOT NULL,
    observed_at DATETIME NOT NULL,
    reported_by VARCHAR(64) DEFAULT 'agent' NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_param_machine_config_key UNIQUE (machine_id, param_key)
);

CREATE INDEX ix_param_machine_config_machine_id ON param_machine_config (machine_id);

CREATE TABLE param_machine_draft (
    id INTEGER NOT NULL,
    machine_id VARCHAR(64) NOT NULL,
    param_key VARCHAR(128) NOT NULL,
    value VARCHAR(1024) DEFAULT '' NOT NULL,
    updated_by VARCHAR(64) DEFAULT '' NOT NULL,
    updated_at DATETIME NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_param_machine_draft_key UNIQUE (machine_id, param_key)
);

CREATE INDEX ix_param_machine_draft_machine_id ON param_machine_draft (machine_id);

CREATE TABLE param_agent_config_version (
    machine_id VARCHAR(64) NOT NULL,
    config_version INTEGER NOT NULL,
    yaml_hash VARCHAR(64) DEFAULT '' NOT NULL,
    yaml_text TEXT NOT NULL,
    rendered_at DATETIME NOT NULL,
    PRIMARY KEY (machine_id, config_version)
);

CREATE TABLE param_token_metric (
    id INTEGER NOT NULL,
    machine_id VARCHAR(64) NOT NULL,
    workload_id INTEGER,
    observed_at DATETIME NOT NULL,
    input_tokens INTEGER DEFAULT '0' NOT NULL,
    output_tokens INTEGER DEFAULT '0' NOT NULL,
    responses INTEGER DEFAULT '0' NOT NULL,
    audio_duration_s FLOAT,
    window_s INTEGER DEFAULT '0' NOT NULL,
    reported_by VARCHAR(64) DEFAULT 'agent' NOT NULL,
    PRIMARY KEY (id)
);

CREATE INDEX ix_param_token_metric_machine_id ON param_token_metric (machine_id);

CREATE TABLE param_lb_rule (
    id INTEGER NOT NULL,
    name VARCHAR(64) NOT NULL,
    priority INTEGER DEFAULT '100' NOT NULL,
    match_type VARCHAR(16) DEFAULT 'default' NOT NULL,
    match_value VARCHAR(255) DEFAULT '' NOT NULL,
    target_kind VARCHAR(16) DEFAULT 'instance' NOT NULL,
    target_value VARCHAR(255) DEFAULT '' NOT NULL,
    share_pct INTEGER,
    sticky_ttl_s INTEGER,
    enabled BOOLEAN DEFAULT '1' NOT NULL,
    updated_by VARCHAR(64) DEFAULT '' NOT NULL,
    created_at DATETIME NOT NULL,
    updated_at DATETIME NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_param_lb_rule_name UNIQUE (name)
);

CREATE TABLE param_lb_affinity (
    affinity_key VARCHAR(128) NOT NULL,
    machine_id VARCHAR(64),
    instance_id VARCHAR(64),
    rule_id INTEGER,
    created_at DATETIME NOT NULL,
    expires_at DATETIME,
    PRIMARY KEY (affinity_key)
);

CREATE INDEX ix_param_lb_affinity_machine_id ON param_lb_affinity (machine_id);

CREATE INDEX ix_param_lb_affinity_expires_at ON param_lb_affinity (expires_at);

CREATE TABLE param_lb_route_log (
    id INTEGER NOT NULL,
    at DATETIME NOT NULL,
    session_key VARCHAR(128) DEFAULT '' NOT NULL,
    rule_id INTEGER,
    matched BOOLEAN DEFAULT '0' NOT NULL,
    instance_id VARCHAR(64),
    sticky_hit BOOLEAN DEFAULT '0' NOT NULL,
    is_canary BOOLEAN DEFAULT '0' NOT NULL,
    input_tokens INTEGER DEFAULT '0' NOT NULL,
    output_tokens INTEGER DEFAULT '0' NOT NULL,
    PRIMARY KEY (id)
);

CREATE INDEX ix_param_lb_route_log_at ON param_lb_route_log (at);

CREATE TABLE param_release (
    id INTEGER NOT NULL,
    version VARCHAR(64) NOT NULL,
    profile_version VARCHAR(64),
    cluster_id VARCHAR(64) DEFAULT '' NOT NULL,
    status VARCHAR(16) DEFAULT 'draft' NOT NULL,
    stage VARCHAR(32) DEFAULT '' NOT NULL,
    rollout_pct INTEGER DEFAULT '0' NOT NULL,
    nodes JSON DEFAULT '[]' NOT NULL,
    changes JSON DEFAULT '[]' NOT NULL,
    created_by VARCHAR(64) DEFAULT '' NOT NULL,
    created_at DATETIME NOT NULL,
    PRIMARY KEY (id)
);

ALTER TABLE turn_latency ADD COLUMN machine_id VARCHAR(64);

ALTER TABLE turn_latency ADD COLUMN instance_id VARCHAR(64);

ALTER TABLE turn_latency ADD COLUMN audio_duration_s FLOAT;

ALTER TABLE param_instance ADD COLUMN machine_id VARCHAR(64);

ALTER TABLE param_cluster ADD COLUMN baseline_profile VARCHAR(64) DEFAULT 'prod' NOT NULL;

UPDATE alembic_version SET version_num='0010_console_lb_backbone' WHERE alembic_version.version_num = '0009_db_registry_and_config';

